create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',avatar_url text,timezone text not null default 'Asia/Bangkok',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.calendars(id uuid primary key default gen_random_uuid(),name text not null,description text,color varchar(7) not null default '#2563EB',owner_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),calendar_id uuid not null references public.calendars(id) on delete cascade,created_by uuid not null references public.profiles(id) on delete cascade,title text not null,description text,location text,starts_at timestamptz not null,ends_at timestamptz not null,is_all_day boolean not null default false,color varchar(7),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint events_valid_period check(ends_at>starts_at));
create index if not exists events_calendar_period_idx on public.events(calendar_id,starts_at,ends_at);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''));insert into public.calendars(name,owner_id) values('ปฏิทินของฉัน',new.id);return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security;alter table public.calendars enable row level security;alter table public.events enable row level security;
create policy "profile own select" on public.profiles for select to authenticated using(id=(select auth.uid()));create policy "profile own update" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "calendar own select" on public.calendars for select to authenticated using(owner_id=(select auth.uid()));create policy "calendar own all" on public.calendars for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy "event own calendar select" on public.events for select to authenticated using(exists(select 1 from public.calendars c where c.id=events.calendar_id and c.owner_id=(select auth.uid())));create policy "event own calendar insert" on public.events for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.calendars c where c.id=events.calendar_id and c.owner_id=(select auth.uid())));create policy "event own calendar update" on public.events for update to authenticated using(exists(select 1 from public.calendars c where c.id=events.calendar_id and c.owner_id=(select auth.uid()))) with check(exists(select 1 from public.calendars c where c.id=events.calendar_id and c.owner_id=(select auth.uid())));create policy "event own calendar delete" on public.events for delete to authenticated using(exists(select 1 from public.calendars c where c.id=events.calendar_id and c.owner_id=(select auth.uid())));
create or replace function public.create_personal_event(p_title text,p_description text,p_location text,p_starts_at timestamptz,p_ends_at timestamptz,p_color text,p_is_all_day boolean) returns uuid language plpgsql security invoker set search_path=public as $$ declare v_id uuid;v_calendar uuid;begin select id into v_calendar from public.calendars where owner_id=auth.uid() order by created_at limit 1;if v_calendar is null then insert into public.calendars(name,owner_id) values('ปฏิทินของฉัน',auth.uid()) returning id into v_calendar;end if;insert into public.events(calendar_id,created_by,title,description,location,starts_at,ends_at,color,is_all_day) values(v_calendar,auth.uid(),p_title,p_description,p_location,p_starts_at,p_ends_at,p_color,p_is_all_day) returning id into v_id;return v_id;end;$$;grant execute on function public.create_personal_event(text,text,text,timestamptz,timestamptz,text,boolean) to authenticated;